Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label style="font-weight:bold;margin-bottom:2px">Ray view</label>
<div style="display:flex;gap:4px">
  <button id="btnAllRays" class="active">All rays</button>
  <button id="btnSingleRay">Single ray</button>
</div>
<label>Selected ray: <span id="rayIdxLabel">2</span></label>
<input type="range" id="raySlider" min="0" max="6" step="1" value="2">
<button id="btnPulse">▶ Play sound pulses</button>
<label style="font-size:10px;color:#555;margin-top:4px">Drag to orbit · Click a ray to isolate it</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──────────────────────────────────────────────────────────
// dome outer  → parametric BufferGeometry 64×32, vertex colors #4a90d9→#eaf3fb, FrontSide, MeshStandardMaterial
// dome inner  → same geometry, BackSide, MeshBasicMaterial #e6d2ac
// floor       → CircleGeometry(1,64) rotated flat, scaled (3,1,2), MeshBasicMaterial #ecd9b4
// base slab   → CylinderGeometry(1,1,0.18,64) scaled (3.12,1,2.12), y=-0.09, MeshBasicMaterial #565a5e
// cut rim     → Line along semi-ellipse x²/9+y²/4=1 z=0, color #8a6d3b
// focus F'    → SphereGeometry(0.07) #10254a at (-√5,0,0)
// focus F     → SphereGeometry(0.07) #10254a at (+√5,0,0)
// rays ×7     → Line (2 segments) + ConeGeometry(0.055,0.14) arrowheads, #16386b
// colliders   → TubeGeometry r=0.14 invisible, for ray click selection
// pulses ×7   → SphereGeometry(0.055) emissive #ffcc00, animated F'→P→F

const a = 3, b = 2;
const c = Math.sqrt(a * a - b * b); // ≈2.236
const Fp = new THREE.Vector3(-c, 0, 0);
const Fq = new THREE.Vector3(c, 0, 0);

// ── Lighting ───────────────────────────────────────────────────────────────
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(3, 5, 4);
scene.add(dirLight);

// ── Dome geometry (parametric) ─────────────────────────────────────────────
const uSeg = 64, vSeg = 32;
const domePositions = [];
const domeColors = [];
const domeIndices = [];
const rimColor = new THREE.Color(0x4a90d9);
const topColor = new THREE.Color(0xeaf3fb);

for (let j = 0; j <= vSeg; j++) {
  const theta = (j / vSeg) * (Math.PI / 2);
  const sinT = Math.sin(theta), cosT = Math.cos(theta);
  const t = cosT; // 0 at rim, 1 at top
  const col = rimColor.clone().lerp(topColor, t);
  for (let i = 0; i <= uSeg; i++) {
    const phi = (i / uSeg) * Math.PI;
    const x = a * sinT * Math.cos(phi);
    const y = b * cosT;
    const z = b * sinT * Math.sin(phi);
    domePositions.push(x, y, z);
    domeColors.push(col.r, col.g, col.b);
  }
}
for (let j = 0; j < vSeg; j++) {
  for (let i = 0; i < uSeg; i++) {
    const idx0 = j * (uSeg + 1) + i;
    const idx1 = idx0 + 1;
    const idx2 = idx0 + (uSeg + 1);
    const idx3 = idx2 + 1;
    domeIndices.push(idx0, idx2, idx1);
    domeIndices.push(idx1, idx2, idx3);
  }
}
const domeGeo = new THREE.BufferGeometry();
domeGeo.setAttribute('position', new THREE.Float32BufferAttribute(domePositions, 3));
domeGeo.setAttribute('color', new THREE.Float32BufferAttribute(domeColors, 3));
domeGeo.setIndex(domeIndices);
domeGeo.computeVertexNormals();

const outerMat = new THREE.MeshStandardMaterial({
  vertexColors: true, side: THREE.FrontSide, roughness: 0.55, metalness: 0.05
});
const domeOuter = new THREE.Mesh(domeGeo, outerMat);
scene.add(domeOuter);

const innerMat = new THREE.MeshBasicMaterial({ color: 0xe6d2ac, side: THREE.BackSide });
const domeInner = new THREE.Mesh(domeGeo, innerMat);
scene.add(domeInner);

// ── Floor ──────────────────────────────────────────────────────────────────
const floorGeo = new THREE.CircleGeometry(1, 64);
floorGeo.rotateX(-Math.PI / 2);
floorGeo.scale(3, 1, 2);
const floorMesh = new THREE.Mesh(floorGeo, new THREE.MeshBasicMaterial({ color: 0xecd9b4 }));
floorMesh.position.y = 0.001;
scene.add(floorMesh);

// ── Base slab ──────────────────────────────────────────────────────────────
const slabGeo = new THREE.CylinderGeometry(1, 1, 0.18, 64);
slabGeo.scale(3.12, 1, 2.12);
const slabMesh = new THREE.Mesh(slabGeo, new THREE.MeshBasicMaterial({ color: 0x565a5e }));
slabMesh.position.y = -0.09;
scene.add(slabMesh);

// ── Cut rim line ───────────────────────────────────────────────────────────
const rimPts = [];
for (let i = 0; i <= 64; i++) {
  const ang = (i / 64) * Math.PI;
  rimPts.push(new THREE.Vector3(3 * Math.cos(ang), 2 * Math.sin(ang), 0));
}
const rimLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(rimPts),
  new THREE.LineBasicMaterial({ color: 0x8a6d3b, linewidth: 2 })
);
scene.add(rimLine);

// ── Focus points ───────────────────────────────────────────────────────────
const focusGeo = new THREE.SphereGeometry(0.07, 16, 16);
const focusMat = new THREE.MeshBasicMaterial({ color: 0x10254a });
const focusFp = new THREE.Mesh(focusGeo, focusMat);
focusFp.position.copy(Fp);
scene.add(focusFp);
const focusF = new THREE.Mesh(focusGeo, focusMat.clone());
focusF.position.copy(Fq);
scene.add(focusF);

// ── Ray paths ──────────────────────────────────────────────────────────────
const rayParams = [
  { phi: 0.50 * Math.PI, theta: 0.12 * Math.PI },
  { phi: 0.35 * Math.PI, theta: 0.22 * Math.PI },
  { phi: 0.65 * Math.PI, theta: 0.22 * Math.PI },
  { phi: 0.40 * Math.PI, theta: 0.35 * Math.PI },
  { phi: 0.60 * Math.PI, theta: 0.35 * Math.PI },
  { phi: 0.45 * Math.PI, theta: 0.28 * Math.PI },
  { phi: 0.55 * Math.PI, theta: 0.30 * Math.PI },
];

const rayColor = 0x16386b;
const rayGroups = [];
const rayColliders = [];
const reflectionPoints = [];

function createArrowhead(from, to, parent) {
  const mid = from.clone().add(to).multiplyScalar(0.5);
  const dir = to.clone().sub(from).normalize();
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.055, 0.14, 8),
    new THREE.MeshBasicMaterial({ color: rayColor })
  );
  cone.position.copy(mid);
  const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  cone.quaternion.copy(quat);
  parent.add(cone);
  return cone;
}

for (let r = 0; r < rayParams.length; r++) {
  const { phi, theta } = rayParams[r];
  const P = new THREE.Vector3(
    a * Math.sin(theta) * Math.cos(phi),
    b * Math.cos(theta),
    b * Math.sin(theta) * Math.sin(phi)
  );
  reflectionPoints.push(P);

  const group = new THREE.Group();
  const lineMat = new THREE.LineBasicMaterial({ color: rayColor, transparent: true, opacity: 1 });
  const pts = [Fp.clone(), P.clone(), Fq.clone()];
  const lineGeo = new THREE.BufferGeometry().setFromPoints(pts);
  const line = new THREE.Line(lineGeo, lineMat);
  group.add(line);

  createArrowhead(Fp, P, group);
  createArrowhead(P, Fq, group);

  // Small sphere at reflection point
  const reflDot = new THREE.Mesh(
    new THREE.SphereGeometry(0.045, 8, 8),
    new THREE.MeshBasicMaterial({ color: rayColor })
  );
  reflDot.position.copy(P);
  group.add(reflDot);

  scene.add(group);
  rayGroups.push({ group, lineMat, P });

  // Invisible collider for clicking
  const curvePath = new THREE.CurvePath();
  curvePath.add(new THREE.LineCurve3(Fp.clone(), P.clone()));
  curvePath.add(new THREE.LineCurve3(P.clone(), Fq.clone()));
  const tubeGeo = new THREE.TubeGeometry(curvePath, 32, 0.14, 8, false);
  const tubeMat = new THREE.MeshBasicMaterial({ visible: false });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  tube.userData.rayIndex = r;
  scene.add(tube);
  rayColliders.push(tube);
  registerInteractive(tube, {
    title: `Ray ${r + 1}`,
    body: `This ray leaves F', strikes the dome at P, and reflects to F. The angle of incidence equals the angle of reflection at P.`,
    tooltip: `Click to isolate ray ${r + 1}`,
    onClick: () => { setRayView('single'); setRayIndex(r); }
  });
}

// ── State ──────────────────────────────────────────────────────────────────
let currentView = 'all'; // 'all' | 'single'
let currentRayIdx = 2;
let pulseActive = false;

function updateRayVisibility() {
  for (let i = 0; i < rayGroups.length; i++) {
    const { group, lineMat } = rayGroups[i];
    if (currentView === 'all') {
      lineMat.opacity = 1;
      group.traverse(o => { if (o.material && o.material !== lineMat) o.material.opacity = 1; if (o.material) o.material.transparent = true; });
      group.visible = true;
    } else {
      if (i === currentRayIdx) {
        lineMat.opacity = 1;
        group.visible = true;
        group.traverse(o => { if (o.material) { o.material.opacity = 1; o.material.transparent = true; } });
      } else {
        lineMat.opacity = 0.12;
        group.visible = true;
        group.traverse(o => { if (o.material) { o.material.opacity = 0.12; o.material.transparent = true; } });
      }
    }
  }
}

function setRayView(mode) {
  currentView = mode;
  document.getElementById('btnAllRays').classList.toggle('active', mode === 'all');
  document.getElementById('btnSingleRay').classList.toggle('active', mode === 'single');
  updateRayVisibility();
}

function setRayIndex(idx) {
  currentRayIdx = Math.max(0, Math.min(6, idx));
  document.getElementById('raySlider').value = currentRayIdx;
  document.getElementById('rayIdxLabel').textContent = currentRayIdx;
  updateRayVisibility();
}

// ── UI wiring ──────────────────────────────────────────────────────────────
document.getElementById('btnAllRays').addEventListener('click', () => setRayView('all'));
document.getElementById('btnSingleRay').addEventListener('click', () => setRayView('single'));
document.getElementById('raySlider').addEventListener('input', (e) => setRayIndex(parseInt(e.target.value)));

// ── Pulse animation ────────────────────────────────────────────────────────
const pulseSpheres = [];
const pulseMat = new THREE.MeshBasicMaterial({ color: 0xffcc00, transparent: true, opacity: 0.9 });
for (let i = 0; i < 7; i++) {
  const sphere = new THREE.Mesh(new THREE.SphereGeometry(0.055, 12, 12), pulseMat.clone());
  sphere.visible = false;
  scene.add(sphere);
  pulseSpheres.push(sphere);
}

let pulseTime = 0;
let lastPulseFrame = performance.now();
const PULSE_DURATION = 2.0; // seconds per full trip
const PULSE_STAGGER = 0.28; // seconds between each pulse start

function updatePulses() {
  if (!pulseActive) return;
  const now = performance.now();
  const dt = (now - lastPulseFrame) / 1000;
  lastPulseFrame = now;
  pulseTime += dt;

  for (let i = 0; i < 7; i++) {
    const localT = ((pulseTime - i * PULSE_STAGGER) % (PULSE_DURATION + 0.5)) / PULSE_DURATION;
    const sphere = pulseSpheres[i];
    if (localT < 0 || localT > 1) {
      sphere.visible = false;
      continue;
    }
    sphere.visible = true;
    const P = reflectionPoints[i];
    if (localT < 0.5) {
      const t2 = localT / 0.5;
      sphere.position.lerpVectors(Fp, P, t2);
    } else {
      const t2 = (localT - 0.5) / 0.5;
      sphere.position.lerpVectors(P, Fq, t2);
    }
  }
}

function animatePulseLoop() {
  requestAnimationFrame(animatePulseLoop);
  updatePulses();
}
animatePulseLoop();

document.getElementById('btnPulse').addEventListener('click', () => {
  pulseActive = !pulseActive;
  const btn = document.getElementById('btnPulse');
  btn.textContent = pulseActive ? '⏸ Stop pulses' : '▶ Play sound pulses';
  btn.classList.toggle('active', pulseActive);
  if (!pulseActive) {
    pulseSpheres.forEach(s => s.visible = false);
  } else {
    pulseTime = 0;
    lastPulseFrame = performance.now();
  }
});

// ── Camera view ────────────────────────────────────────────────────────────
setCameraView({
  projection: 'perspective',
  azimuthDeg: 55,
  elevationDeg: 22,
  rollDeg: 0,
  heightFraction: 0.7
});

// ── Labels ────────────────────────────────────────────────────────────────
addLabel('<i>F\u2032</i>', new THREE.Vector3(Fp.x - 0.15, -0.12, 0.15), { fontSize: '15px', bold: true });
addLabel('<i>F</i>', new THREE.Vector3(Fq.x + 0.15, -0.12, 0.15), { fontSize: '15px', bold: true });

// ── Initial state ──────────────────────────────────────────────────────────
updateRayVisibility();
// @FIGURE_CODE_END

