// @FIGURE_CODE_BEGIN
// ── Element specs ──────────────────────────────────────────────────────────
// dome shell  → parametric quarter-ellipsoid (z>=0,y>=0) 64×32, vertex colors #3f86d6→#eef6fd,
//               MeshBasicMaterial transparent opacity 0.30 DoubleSide depthWrite false (see-through)
// floor       → half-ellipse (z>=0) CircleGeometry(1,64,π,π) rotX, scale (3,1,2), #ecd9b4 opaque
// base slab   → half-CylinderGeometry θ∈[-π/2,π/2] scaled (3.12,1,2.12) h0.18 y-0.09 #565a5e opaque
// cut rim     → Line semi-ellipse x=3cos t,y=2sin t,z=0, #8a6d3b
// focus F'    → SphereGeometry(0.08) #10254a at (-√5,0,0)
// focus F     → SphereGeometry(0.08) #10254a at (+√5,0,0)
// rays ×7     → Line(2 seg)+Cone arrowheads #16386b opaque renderOrder 2 (visible through dome)
// colliders   → TubeGeometry r=0.16 invisible, ray click selection
// pulses ×7   → SphereGeometry(0.06) #ffcc00 animated F'→P→F

const a = 3, b = 2;
const c = Math.sqrt(a * a - b * b); // ≈2.236
const Fp = new THREE.Vector3(-c, 0, 0);
const Fq = new THREE.Vector3(c, 0, 0);

// ── Dome shell (transparent blue gradient quarter-ellipsoid) ───────────────
const uSeg = 64, vSeg = 32;
const domePositions = [], domeColors = [], domeIndices = [];
const rimColor = new THREE.Color(0x3f86d6);
const topColor = new THREE.Color(0xeef6fd);
for (let j = 0; j <= vSeg; j++) {
  const theta = (j / vSeg) * (Math.PI / 2);
  const sinT = Math.sin(theta), cosT = Math.cos(theta);
  const col = rimColor.clone().lerp(topColor, cosT);
  for (let i = 0; i <= uSeg; i++) {
    const phi = (i / uSeg) * Math.PI; // 0..π → z>=0 half
    domePositions.push(a * sinT * Math.cos(phi), b * cosT, b * sinT * Math.sin(phi));
    domeColors.push(col.r, col.g, col.b);
  }
}
for (let j = 0; j < vSeg; j++) for (let i = 0; i < uSeg; i++) {
  const i0 = j * (uSeg + 1) + i, i1 = i0 + 1, i2 = i0 + (uSeg + 1), i3 = i2 + 1;
  domeIndices.push(i0, i2, i1, i1, i2, i3);
}
const domeGeo = new THREE.BufferGeometry();
domeGeo.setAttribute('position', new THREE.Float32BufferAttribute(domePositions, 3));
domeGeo.setAttribute('color', new THREE.Float32BufferAttribute(domeColors, 3));
domeGeo.setIndex(domeIndices);
domeGeo.computeVertexNormals();
const domeMat = new THREE.MeshBasicMaterial({
  vertexColors: true, transparent: true, opacity: 0.30,
  side: THREE.DoubleSide, depthWrite: false
});
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.renderOrder = 1;
scene.add(dome);

// ── Floor (half-ellipse under the shell, z>=0) ────────────────────────────
const floorGeo = new THREE.CircleGeometry(1, 64, Math.PI, Math.PI);
floorGeo.rotateX(-Math.PI / 2);
floorGeo.scale(a, 1, b);
const floorMesh = new THREE.Mesh(floorGeo, new THREE.MeshBasicMaterial({ color: 0xecd9b4 }));
floorMesh.position.y = 0.001;
floorMesh.renderOrder = 0;
scene.add(floorMesh);

// ── Base slab (dark half-cylinder rim) ────────────────────────────────────
const slabGeo = new THREE.CylinderGeometry(1, 1, 0.18, 64, 1, false, -Math.PI / 2, Math.PI);
slabGeo.scale(a + 0.12, 1, b + 0.12);
const slabMesh = new THREE.Mesh(slabGeo, new THREE.MeshBasicMaterial({ color: 0x565a5e }));
slabMesh.position.y = -0.09;
slabMesh.renderOrder = 0;
scene.add(slabMesh);

// ── Cut rim line (open face outline) ──────────────────────────────────────
const rimPts = [];
for (let i = 0; i <= 64; i++) {
  const t = (i / 64) * Math.PI;
  rimPts.push(new THREE.Vector3(a * Math.cos(t), b * Math.sin(t), 0));
}
const rimLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(rimPts),
  new THREE.LineBasicMaterial({ color: 0x8a6d3b })
);
rimLine.renderOrder = 2;
scene.add(rimLine);

// ── Foci ──────────────────────────────────────────────────────────────────
const focusGeo = new THREE.SphereGeometry(0.08, 16, 16);
const focusMat = new THREE.MeshBasicMaterial({ color: 0x10254a });
const focusFp = new THREE.Mesh(focusGeo, focusMat); focusFp.position.copy(Fp); focusFp.renderOrder = 3; scene.add(focusFp);
const focusF = new THREE.Mesh(focusGeo, focusMat.clone()); focusF.position.copy(Fq); focusF.renderOrder = 3; scene.add(focusF);

// ── Rays ──────────────────────────────────────────────────────────────────
const rayParams = [
  { phi: 0.50 * Math.PI, theta: 0.16 * Math.PI },
  { phi: 0.32 * Math.PI, theta: 0.30 * Math.PI },
  { phi: 0.68 * Math.PI, theta: 0.30 * Math.PI },
  { phi: 0.40 * Math.PI, theta: 0.42 * Math.PI },
  { phi: 0.60 * Math.PI, theta: 0.42 * Math.PI },
  { phi: 0.45 * Math.PI, theta: 0.24 * Math.PI },
  { phi: 0.55 * Math.PI, theta: 0.34 * Math.PI },
];
const rayColor = 0x16386b;
const rayGroups = [], rayColliders = [], reflectionPoints = [];

function addArrow(from, to, parent) {
  const mid = from.clone().add(to).multiplyScalar(0.5);
  const dir = to.clone().sub(from).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.16, 10),
    new THREE.MeshBasicMaterial({ color: rayColor }));
  cone.position.copy(mid);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  cone.renderOrder = 2;
  parent.add(cone);
}

for (let r = 0; r < rayParams.length; r++) {
  const { phi, theta } = rayParams[r];
  const P = new THREE.Vector3(
    a * Math.sin(theta) * Math.cos(phi),
    b * Math.cos(theta),
    b * Math.sin(theta) * Math.sin(phi)
  );
  reflectionPoints.push(P);
  const group = new THREE.Group();
  const lineMat = new THREE.LineBasicMaterial({ color: rayColor, transparent: true, opacity: 1 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([Fp.clone(), P.clone(), Fq.clone()]), lineMat);
  line.renderOrder = 2;
  group.add(line);
  addArrow(Fp, P, group);
  addArrow(P, Fq, group);
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 10, 10), new THREE.MeshBasicMaterial({ color: rayColor }));
  dot.position.copy(P); dot.renderOrder = 2; group.add(dot);
  scene.add(group);
  rayGroups.push({ group, lineMat, P });

  const path = new THREE.CurvePath();
  path.add(new THREE.LineCurve3(Fp.clone(), P.clone()));
  path.add(new THREE.LineCurve3(P.clone(), Fq.clone()));
  const tube = new THREE.Mesh(new THREE.TubeGeometry(path, 32, 0.16, 8, false),
    new THREE.MeshBasicMaterial({ visible: false }));
  tube.userData.rayIndex = r;
  scene.add(tube);
  rayColliders.push(tube);
  registerInteractive(tube, {
    title: `Ray ${r + 1}`,
    body: `This ray leaves F', strikes the dome at P, and reflects to F. The angle of incidence equals the angle of reflection at P — every ray from one focus passes through the other.`,
    tooltip: `Click to isolate ray ${r + 1}`,
    onClick: () => { setRayView('single'); setRayIndex(r); }
  });
}

// ── State & visibility ────────────────────────────────────────────────────
let currentView = 'all', currentRayIdx = 2;
function setOpacity(v) {
  for (const { group } of rayGroups) group.traverse(o => {
    if (o.material && o.material.transparent) o.material.opacity = (o.userData.baseOp ?? 1) * v;
  });
}
function updateRayVisibility() {
  for (let i = 0; i < rayGroups.length; i++) {
    const { group, lineMat } = rayGroups[i];
    group.visible = true;
    let f = 1;
    if (currentView === 'single' && i !== currentRayIdx) f = 0.12;
    lineMat.opacity = f;
    group.traverse(o => { if (o.material && o.material !== lineMat) { o.material.transparent = true; o.material.opacity = f; } });
  }
}
function setRayView(mode) {
  currentView = mode;
  document.getElementById('btnAllRays').classList.toggle('active', mode === 'all');
  document.getElementById('btnSingleRay').classList.toggle('active', mode === 'single');
  updateRayVisibility();
}
function setRayIndex(idx) {
  currentRayIdx = Math.max(0, Math.min(6, idx));
  document.getElementById('raySlider').value = currentRayIdx;
  document.getElementById('rayIdxLabel').textContent = currentRayIdx;
  updateRayVisibility();
}
document.getElementById('btnAllRays').addEventListener('click', () => setRayView('all'));
document.getElementById('btnSingleRay').addEventListener('click', () => setRayView('single'));
document.getElementById('raySlider').addEventListener('input', e => setRayIndex(parseInt(e.target.value)));
document.getElementById('opSlider').addEventListener('input', e => {
  const v = parseFloat(e.target.value);
  domeMat.opacity = v;
  document.getElementById('opLabel').textContent = v.toFixed(2);
});

// ── Pulses ────────────────────────────────────────────────────────────────
const pulseSpheres = [];
for (let i = 0; i < 7; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.06, 12, 12),
    new THREE.MeshBasicMaterial({ color: 0xffcc00, transparent: true, opacity: 0.95 }));
  s.visible = false; s.renderOrder = 4; scene.add(s); pulseSpheres.push(s);
}
let pulseActive = false, pulseTime = 0, lastPulse = performance.now();
const PD = 2.0, PS = 0.28;
function pulseLoop() {
  requestAnimationFrame(pulseLoop);
  if (!pulseActive) return;
  const now = performance.now(); pulseTime += (now - lastPulse) / 1000; lastPulse = now;
  for (let i = 0; i < 7; i++) {
    const lt = ((pulseTime - i * PS) % (PD + 0.5)) / PD;
    const s = pulseSpheres[i];
    if (lt < 0 || lt > 1) { s.visible = false; continue; }
    s.visible = true;
    const P = reflectionPoints[i];
    if (lt < 0.5) s.position.lerpVectors(Fp, P, lt / 0.5);
    else s.position.lerpVectors(P, Fq, (lt - 0.5) / 0.5);
  }
}
pulseLoop();
document.getElementById('btnPulse').addEventListener('click', () => {
  pulseActive = !pulseActive;
  const btn = document.getElementById('btnPulse');
  btn.textContent = pulseActive ? '⏸ Stop pulses' : '▶ Play sound pulses';
  btn.classList.toggle('active', pulseActive);
  if (!pulseActive) pulseSpheres.forEach(s => s.visible = false);
  else { pulseTime = 0; lastPulse = performance.now(); }
});

// ── Camera: look into the open cut face ───────────────────────────────────
setCameraView({
  projection: 'perspective',
  azimuthDeg: -90,
  elevationDeg: 20,
  heightFraction: 0.72,
  target: [0, 0.7, 0.3]
});

// ── Labels ────────────────────────────────────────────────────────────────
addLabel('<i>F\u2032</i>', new THREE.Vector3(Fp.x, -0.02, -0.35), { fontSize: '17px', bold: true });
addLabel('<i>F</i>', new THREE.Vector3(Fq.x, -0.02, -0.35), { fontSize: '17px', bold: true });

updateRayVisibility();
// @FIGURE_CODE_END

