<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element specs ──────────────────────────────────────────────────────────
// dome shell  → parametric quarter-ellipsoid (z>=0,y>=0) a=3,b=2.4, 72×36, vertex colors
//               #2f7fd0→#eaf4fd, MeshBasicMaterial transparent 0.28 DoubleSide depthWrite false
// floor       → half-ellipse (z>=0) CircleGeometry rotX scale(3,1,2.4) #ecd9b4 opaque
// base slab   → half-CylinderGeometry scaled (3.14,1,2.54) h0.20 y-0.10 #4c5054 opaque
// inner hint  → filled semi-ellipse (z=0) translucent #1c3a5e opacity 0.10 (inner-surface hint)
// cut rim     → TubeGeometry r=0.075 along semi-ellipse #9aa0a6 (shaded 3D opening rim)
// outer rim   → TubeGeometry r=0.05 along top outer arc #b9c0c8 (silver shell edge)
// focus F'    → SphereGeometry(0.09) #10254a at (+c,0,0)  [screen-LEFT under azimuth -90]
// focus F     → SphereGeometry(0.09) #10254a at (-c,0,0)  [screen-RIGHT]
// rays ×7     → Line(2 seg)+Cone arrowheads #16386b opaque renderOrder 3
// colliders   → TubeGeometry r=0.17 invisible for click selection
// pulses ×7   → SphereGeometry(0.06) #ffcc00 animated F'→P→F

const a = 3, b = 2.4;
const c = Math.sqrt(a * a - b * b); // ≈1.8
// Screen mapping under azimuthDeg=-90 puts world +X on screen-LEFT.
const Fprime = new THREE.Vector3(c, 0, 0);   // F' → left on screen
const Ffocus = new THREE.Vector3(-c, 0, 0);  // F  → right on screen

// ── Dome shell (transparent blue gradient quarter-ellipsoid) ───────────────
const uSeg = 72, vSeg = 36;
const domePositions = [], domeColors = [], domeIndices = [];
const rimColor = new THREE.Color(0x2f7fd0);
const topColor = new THREE.Color(0xeaf4fd);
for (let j = 0; j <= vSeg; j++) {
  const theta = (j / vSeg) * (Math.PI / 2);
  const sinT = Math.sin(theta), cosT = Math.cos(theta);
  const col = rimColor.clone().lerp(topColor, cosT);
  for (let i = 0; i <= uSeg; i++) {
    const phi = (i / uSeg) * Math.PI; // 0..π → z>=0 half (interior back wall)
    domePositions.push(a * sinT * Math.cos(phi), b * cosT, b * sinT * Math.sin(phi));
    domeColors.push(col.r, col.g, col.b);
  }
}
for (let j = 0; j < vSeg; j++) for (let i = 0; i < uSeg; i++) {
  const i0 = j * (uSeg + 1) + i, i1 = i0 + 1, i2 = i0 + (uSeg + 1), i3 = i2 + 1;
  domeIndices.push(i0, i2, i1, i1, i2, i3);
}
const domeGeo = new THREE.BufferGeometry();
domeGeo.setAttribute('position', new THREE.Float32BufferAttribute(domePositions, 3));
domeGeo.setAttribute('color', new THREE.Float32BufferAttribute(domeColors, 3));
domeGeo.setIndex(domeIndices);
domeGeo.computeVertexNormals();
const domeMat = new THREE.MeshBasicMaterial({
  vertexColors: true, transparent: true, opacity: 0.28,
  side: THREE.DoubleSide, depthWrite: false
});
const dome = new THREE.Mesh(domeGeo, domeMat);
dome.renderOrder = 1;
scene.add(dome);

// ── Floor (half-ellipse bowl bottom, z>=0) ────────────────────────────────
const floorGeo = new THREE.CircleGeometry(1, 72, Math.PI, Math.PI);
floorGeo.rotateX(-Math.PI / 2);
floorGeo.scale(a, 1, b);
const floorMesh = new THREE.Mesh(floorGeo, new THREE.MeshBasicMaterial({ color: 0xecd9b4 }));
floorMesh.position.y = 0.001;
floorMesh.renderOrder = 0;
scene.add(floorMesh);

// ── Base slab (dark half-cylinder rim) ────────────────────────────────────
const slabGeo = new THREE.CylinderGeometry(1, 1, 0.20, 72, 1, false, -Math.PI / 2, Math.PI);
slabGeo.scale(a + 0.14, 1, b + 0.14);
const slabMesh = new THREE.Mesh(slabGeo, new THREE.MeshBasicMaterial({ color: 0x4c5054 }));
slabMesh.position.y = -0.10;
slabMesh.renderOrder = 0;
scene.add(slabMesh);

// ── Inner-opening hint (filled semi-ellipse at the cut plane) ─────────────
const hintShape = new THREE.Shape();
hintShape.moveTo(-a, 0);
hintShape.absellipse(0, 0, a, b, Math.PI, 0, true);
hintShape.lineTo(-a, 0);
const hintGeo = new THREE.ShapeGeometry(hintShape, 48);
const hintMesh = new THREE.Mesh(hintGeo, new THREE.MeshBasicMaterial({
  color: 0x1c3a5e, transparent: true, opacity: 0.10, side: THREE.DoubleSide, depthWrite: false
}));
hintMesh.renderOrder = 0;
scene.add(hintMesh);

// ── Cut rim (shaded 3D elliptical opening) ────────────────────────────────
class SemiEllipseCurve extends THREE.Curve {
  getPoint(t, target = new THREE.Vector3()) {
    const ang = Math.PI * (1 - t); // t:0→π  (left→right over the top)
    return target.set(a * Math.cos(ang), b * Math.sin(ang), 0);
  }
}
const rimCurve = new SemiEllipseCurve();
const rimTube = new THREE.Mesh(
  new THREE.TubeGeometry(rimCurve, 96, 0.075, 12, false),
  new THREE.MeshBasicMaterial({ color: 0x9aa0a6 })
);
rimTube.renderOrder = 2;
scene.add(rimTube);

// outer silver shell edge (slightly larger, top arc only)
class OuterArcCurve extends THREE.Curve {
  getPoint(t, target = new THREE.Vector3()) {
    const ang = Math.PI * (1 - t);
    return target.set((a + 0.10) * Math.cos(ang), (b + 0.10) * Math.sin(ang), 0);
  }
}
const outerTube = new THREE.Mesh(
  new THREE.TubeGeometry(new OuterArcCurve(), 96, 0.045, 10, false),
  new THREE.MeshBasicMaterial({ color: 0xb9c0c8 })
);
outerTube.renderOrder = 2;
scene.add(outerTube);

// ── Foci ──────────────────────────────────────────────────────────────────
const focusGeo = new THREE.SphereGeometry(0.09, 18, 18);
const focusMat = new THREE.MeshBasicMaterial({ color: 0x10254a });
const mFp = new THREE.Mesh(focusGeo, focusMat); mFp.position.copy(Fprime); mFp.renderOrder = 4; scene.add(mFp);
const mF = new THREE.Mesh(focusGeo, focusMat.clone()); mF.position.copy(Ffocus); mF.renderOrder = 4; scene.add(mF);

// ── Rays ──────────────────────────────────────────────────────────────────
const rayParams = [
  { phi: 0.50 * Math.PI, theta: 0.16 * Math.PI },
  { phi: 0.30 * Math.PI, theta: 0.30 * Math.PI },
  { phi: 0.70 * Math.PI, theta: 0.30 * Math.PI },
  { phi: 0.38 * Math.PI, theta: 0.42 * Math.PI },
  { phi: 0.62 * Math.PI, theta: 0.42 * Math.PI },
  { phi: 0.44 * Math.PI, theta: 0.24 * Math.PI },
  { phi: 0.56 * Math.PI, theta: 0.34 * Math.PI },
];
const rayColor = 0x16386b;
const rayGroups = [], reflectionPoints = [];

function addArrow(from, to, parent) {
  const mid = from.clone().add(to).multiplyScalar(0.5);
  const dir = to.clone().sub(from).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.17, 10),
    new THREE.MeshBasicMaterial({ color: rayColor, transparent: true }));
  cone.position.copy(mid);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  cone.renderOrder = 3;
  parent.add(cone);
}

for (let r = 0; r < rayParams.length; r++) {
  const { phi, theta } = rayParams[r];
  const P = new THREE.Vector3(
    a * Math.sin(theta) * Math.cos(phi),
    b * Math.cos(theta),
    b * Math.sin(theta) * Math.sin(phi)
  );
  reflectionPoints.push(P);
  const group = new THREE.Group();
  const lineMat = new THREE.LineBasicMaterial({ color: rayColor, transparent: true, opacity: 1 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([Fprime.clone(), P.clone(), Ffocus.clone()]), lineMat);
  line.renderOrder = 3;
  group.add(line);
  addArrow(Fprime, P, group);
  addArrow(P, Ffocus, group);
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 10, 10), new THREE.MeshBasicMaterial({ color: rayColor, transparent: true }));
  dot.position.copy(P); dot.renderOrder = 3; group.add(dot);
  scene.add(group);
  rayGroups.push({ group, lineMat });

  const path = new THREE.CurvePath();
  path.add(new THREE.LineCurve3(Fprime.clone(), P.clone()));
  path.add(new THREE.LineCurve3(P.clone(), Ffocus.clone()));
  const tube = new THREE.Mesh(new THREE.TubeGeometry(path, 32, 0.17, 8, false),
    new THREE.MeshBasicMaterial({ visible: false }));
  scene.add(tube);
  registerInteractive(tube, {
    title: `Ray ${r + 1}`,
    body: `This ray leaves F', strikes the dome at P, and reflects to F. The angle of incidence equals the angle of reflection at P — every ray from one focus passes through the other.`,
    tooltip: `Click to isolate ray ${r + 1}`,
    onClick: () => { setRayView('single'); setRayIndex(r); }
  });
}

// ── State & visibility ────────────────────────────────────────────────────
let currentView = 'all', currentRayIdx = 2;
function updateRayVisibility() {
  for (let i = 0; i < rayGroups.length; i++) {
    const { group, lineMat } = rayGroups[i];
    group.visible = true;
    let f = 1;
    if (currentView === 'single' && i !== currentRayIdx) f = 0.10;
    lineMat.opacity = f;
    group.traverse(o => { if (o.material && o.material !== lineMat) { o.material.transparent = true; o.material.opacity = f; } });
  }
}
function setRayView(mode) {
  currentView = mode;
  document.getElementById('btnAllRays').classList.toggle('active', mode === 'all');
  document.getElementById('btnSingleRay').classList.toggle('active', mode === 'single');
  updateRayVisibility();
}
function setRayIndex(idx) {
  currentRayIdx = Math.max(0, Math.min(6, idx));
  document.getElementById('raySlider').value = currentRayIdx;
  document.getElementById('rayIdxLabel').textContent = currentRayIdx;
  updateRayVisibility();
}
document.getElementById('btnAllRays').addEventListener('click', () => setRayView('all'));
